function tick(time){raf=0;const dt=lastTime?Math.min((time-lastTime)/1000,.05):0;lastTime=time;if((motion||mapActive)&&!document.hidden){elapsed+=dt;if(visible.has('game-canvas'))advanceGame(dt);if(visible.has('raw-canvas')||visible.has('smooth-canvas'))advanceComparison(dt);Object.entries(canvases).forEach(([id,o])=>{if(visible.has(id)&&o.ctx&&o.w&&o.h)o.draw(o);});}if((motion||mapActive)&&!document.hidden&&visible.size)raf=requestAnimationFrame(tick);else lastTime=0;}
