function activateTab(button,selector,callback){$$(selector).forEach(b=>{const active=b===button;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});callback(button);}
function bindTabs(selector,callback){const buttons=$$(selector);buttons.forEach((b,i)=>{b.addEventListener('click',()=>activateTab(b,selector,callback));b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%buttons.length;if(e.key==='ArrowLeft')n=(i-1+buttons.length)%buttons.length;if(e.key==='Home')n=0;if(e.key==='End')n=buttons.length-1;if(n!==undefined){e.preventDefault();activateTab(buttons[n],selector,callback);buttons[n].focus();}});});}
