function syncPressed(){$$('[data-key]').forEach(k=>k.classList.toggle('down',pressed.has(k.dataset.key)));}
stage.addEventListener('keydown',e=>{if(e.target!==stage)return;const k=e.key.toLowerCase();if(['a','d','w','arrowleft','arrowright','arrowup',' '].includes(k)){e.preventDefault();pressed.add(k);player.manualUntil=gameClock+8;if((k==='w'||k==='arrowup'||k===' ')&&player.vy===0)player.vy=-220;syncPressed();if(!motion){advanceGame(.05);paintAll();}}});
