stage.addEventListener('pointermove',e=>{if(e.target.closest('.hud-widget'))return;const b=stage.getBoundingClientRect();aim={x:(e.clientX-b.left-viewTransform.x)/viewTransform.s,y:(e.clientY-b.top-viewTransform.y)/viewTransform.s};mouseOffset.x=Math.max(-1,Math.min(1,mouseOffset.x+(e.movementX||0)/90));mouseOffset.y=Math.max(-1,Math.min(1,mouseOffset.y+(e.movementY||0)/90));mouseTrail.push({x:mouseOffset.x,y:mouseOffset.y,t:elapsed});if(mouseTrail.length>160)mouseTrail.shift();if(!motion)paintAll();});
function worldPoint(e){const b=stage.getBoundingClientRect();return {x:(e.clientX-b.left-viewTransform.x)/viewTransform.s,y:(e.clientY-b.top-viewTransform.y)/viewTransform.s};}
