stage.addEventListener('pointermove',e=>{if(!teeDrag)return;const p=worldPoint(e);player.x=Math.max(24,Math.min(976,p.x-teeDrag.dx));player.y=Math.max(60,Math.min(462,p.y-teeDrag.dy));player.vy=0;checkFreeze();paintAll();});
