 $('#gradient-name').style.backgroundImage=gradient;$('#gradient-name').style.animationPlayState=animate&&motion?'running':'paused';$('#skin-preview').style.setProperty('--skin-fill',skin?gradient:'#a88cbb');$('#identity-preview').style.setProperty('--gradient-duration',(11-Number($('#gradient-speed').value)/10)+'s');$('#gradient-speed-output').textContent=$('#gradient-speed').value+'%';$('#identity-status').textContent=(gradientMode==='custom'?'Custom gradient':gradientMode==='rainbow'?'Rainbow colors':'Skin colors')+' · '+(animate?'animated':'still');
 const role=$('#role-select').value,member=role==='Member';$('#indicator-custom').disabled=member;if(member)$('#indicator-custom').checked=false;
 const custom=$('#indicator-custom').checked,indicatorMode=$('#indicator-mode').value;$('#indicator-mode').disabled=!custom;
 $('#role-icon').innerHTML='<defs><linearGradient id="indicator-gradient"><stop stop-color="'+one+'"/><stop offset="1" stop-color="'+two+'"/></linearGradient></defs>'+(role==='Owner'?'<path d="m3 9 6 5 7-10 7 10 6-5-3 17H6Z"/><path d="M6 22h20"/>':'<path d="m16 2 4.5 9.5L30 16l-9.5 4.5L16 30l-4.5-9.5L2 16l9.5-4.5Z"/>');
 $('#role-icon').classList.toggle('role-rgb',custom&&indicatorMode==='rgb');$('#role-icon').style.stroke=custom?(indicatorMode==='gradient'?'url(#indicator-gradient)':one):role==='Owner'?'#eac795':'#b894ff';
