function duration(seconds){if(seconds>=2592000){const m=Math.floor(seconds/2592000),w=Math.floor(seconds%2592000/604800);return m+'mo'+(w?' '+w+'w':'');}if(seconds>=604800){const w=Math.floor(seconds/604800),d=Math.floor(seconds%604800/86400);return w+'w'+(d?' '+d+'d':'');}if(seconds>=86400)return Math.floor(seconds/86400)+'d '+Math.floor(seconds%86400/3600)+'h';return Math.floor(seconds/3600)+'h '+Math.floor(seconds%3600/60)+'m';}
function renderProgress(){
 const p=$('#progress-panel');
 if(progressTab==='history')p.innerHTML='<h3>Your recent sessions</h3><p class="table-caption">Example visits and personal totals.</p><table class="data-table"><thead><tr><th>Map / session</th><th>When</th><th>Time</th><th>Saves</th><th>Freezes</th></tr></thead><tbody>'+records.slice(0,5).map(r=>'<tr><td>'+esc(r.map)+'</td><td>'+esc(r.when)+'</td><td>'+r.time+'</td><td>'+r.saves+'</td><td>'+r.freezes+'</td></tr>').join('')+'</tbody></table>';
 else if(progressTab==='tries')p.innerHTML='<h3>Every attempt counts.</h3><p class="table-caption">A start crossing adds an attempt. The client keeps totals across sessions.</p>'+[['Demo course',stats[0].tries],['Moonlit path',26],['Quiet orbit',14]].map(([name,n])=>'<div class="try-row"><span>'+name+'</span><div><i style="width:'+Math.min(100,n/60*100)+'%"></i></div><strong>'+n+' tries</strong></div>').join('');
 else if(progressTab==='kog'){p.innerHTML='<h3>KoG profile preview</h3><p class="table-caption">Manual player lookup, completed maps and teammate time in one view.</p><div class="stat-strip"><div>Total points<strong>1,248</strong></div><div>Completed maps<strong>84</strong></div><div>Global rank<strong>#316</strong></div></div><label class="select-label" for="kog-filter">Filter example maps</label><select id="kog-filter"><option value="all">All difficulties</option><option value="easy">Easy</option><option value="hard">Hard</option></select><div id="kog-map-results"></div>';$('#kog-filter').addEventListener('change',renderKogMaps);renderKogMaps();}
 else if(progressTab==='finish'){const r=records[0];p.innerHTML='<div class="finish-card-demo"><div><span class="widget-heading">FINISH / NOVACLIENT</span><h3>'+esc(r.map)+'</h3><span class="table-caption">'+esc($('#nickname').value||'Nova')+'</span><div class="finish-time">'+r.time+'</div><span class="table-caption">An example finish, ready to keep.</span></div><div class="tee-large"><div class="tee-body"><i class="eye left"></i><i class="eye right"></i></div><i class="foot left"></i><i class="foot right"></i></div><p>'+r.saves+' saves · '+r.freezes+' freezes · '+stats[0].lasts+' last-alive moments</p></div><div class="finish-export"><button id="export-card" class="chip">Export demo card as PNG</button></div>';$('#export-card').addEventListener('click',exportCard);}
 else{p.innerHTML='<h3>/leaderboard</h3><p class="table-caption">Compare personal totals through the Discord command. Example ranking below.</p><div class="leaderboard-controls"><select id="leaderboard-metric" aria-label="Leaderboard metric">'+['playtime','freezes','lasts','saves','tries','deaths'].map(m=>'<option>'+m+'</option>').join('')+'</select></div><div id="demo-leaderboard"></div>';$('#leaderboard-metric').addEventListener('change',renderLeaderboard);renderLeaderboard();}
}
function renderKogMaps(){const mode=$('#kog-filter').value,maps=[['Moonlit path','Easy','00:51.24'],['Quiet orbit','Hard','01:12.80'],['Demo course','Easy','00:46.19']].filter(m=>mode==='all'||m[1].toLowerCase()===mode);$('#kog-map-results').innerHTML='<table class="data-table"><thead><tr><th>Completed map</th><th>Difficulty</th><th>Best time</th></tr></thead><tbody>'+maps.map(m=>'<tr>'+m.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</tbody></table>';}
function renderLeaderboard(){const metric=$('#leaderboard-metric').value,rows=[...stats].sort((a,b)=>b[metric]-a[metric]);$('#demo-leaderboard').innerHTML='<table class="data-table"><thead><tr><th>Rank</th><th>Player</th><th>'+esc(metric)+'</th></tr></thead><tbody>'+rows.map((s,i)=>'<tr><td>#'+(i+1)+'</td><td>'+esc(s.name)+'</td><td>'+(metric==='playtime'?duration(s[metric]):s[metric])+'</td></tr>').join('')+'</tbody></table>';}
